%[text] ## Load, clean, and build SARIMA + Fourier Regressors model
%[text] This script explores the electricity usage dataset for a single client. The main idea is to use a fourier regression (using sine and cosine) to capture the yearly trend, then using a SARIMA model to capture the weekly trend. First the fourier model is fit - this is used to capture the residual values, which are then used to determine the parameters for SARIMA through ACF and PACF. Then, the model is fit - we refit the fourier regression in tandem with the SARIMA model, rather than using the original fit (through regARIMA).
%[text] 
%[text] TODO 
%[text] - Add in holiday indicator? As is, the model can't capture the spike during the holidays (late dec, early jan) \
clear; clc; close all
%%
%[text] Load dataset
opts = detectImportOptions('LD2011_2014.txt', ...
    'Delimiter', ';', 'DecimalSeparator', ',');

opts = setvartype(opts, 1, 'datetime');
opts = setvaropts(opts, 1, 'InputFormat', 'yyyy-MM-dd HH:mm:ss');
T = readtable('LD2011_2014.txt', opts);
T.Properties.VariableNames{1} = 'Time';
TT = table2timetable(T, 'RowTimes', 'Time');
%%
%[text] Choose client, combine into daily avg
client = 'MT_103';
% client = 'MT_200'
x = TT(:, client);

% Trim leading zeros (before client connected)
first = find(x.(client) > 0, 1);
x = x(first:end, :);

% Combine into daily readings
xd = retime(x, 'daily', 'mean');
%%
%[text] **Plot**
%[text] Things to notice - yearly cyclic pattern, weekly pattern, sharp drops on Christmas and New Years day.
plot(xd.Time, xd.(client)); title('Raw Data') %[output:880497d9]
%%
%[text] Train-Test split
disp(xd.Time(1)); disp(xd.Time(end)); %[output:897fab09]

cutoff = datetime(2014, 1, 1); % Train from 2012 & 2013, test on 2014

tAll = xd.Time;
yAll = xd.(client);

trainIdx = tAll < cutoff;
testIdx = tAll >= cutoff;

timeTrain = tAll(trainIdx); yTrainRaw = yAll(trainIdx);
timeTest = tAll(testIdx); yTestRaw = yAll(testIdx);
%%
%[text] Normalize - From ADF test for stationarity, h = 1 =\> no need to difference
yTrainMean = mean(yTrainRaw);
yTrainStd = std(yTrainRaw);

yTrain = (yTrainRaw - yTrainMean) / yTrainStd;
plot(timeTrain, yTrain); title('Normalized Training Data') %[output:3bad63b5]
adftest(yTrain) %[output:79036eb9]

yTest = (yTestRaw - yTrainMean) / yTrainStd;
%%
%[text] Yearly Fourier terms - captures yearly trend, while SARIMA will capture weekly seasonality
tTrain = days(timeTrain - timeTrain(1)); % Days since first day - used for fourier series
m = 365.25; % yearly cycle
n = numel(tTrain);

% Choosing K - elbow at 2
Kmax = 8;
aicK = zeros(Kmax,1);
for K = 1:Kmax
    Xk = zeros(n, 2*K);
    for k = 1:K
        Xk(:,2*k-1) = sin(2*pi*k*tTrain/m);
        Xk(:,2*k)   = cos(2*pi*k*tTrain/m);
    end
    aicK(K) = fitlm(Xk, yTrain(:)).ModelCriterion.AIC;
end
figure; plot(1:Kmax, aicK, '-o'); xlabel('K'); ylabel('AIC') %[output:8a3bacb4]

% Compute w/ chosen K value
K = 2;
Xfourier = zeros(n, 2*K); % Two cols per harmonic
for k = 1:K
    Xfourier(:, 2*k-1) = sin(2*pi*k*tTrain/m);
    Xfourier(:, 2*k) = cos(2*pi*k*tTrain/m);
end

Xext = [ones(n, 1) Xfourier]; % adds intercept col
beta = Xext \ yTrain(:); % least-squares coeff
yFourier = Xext * beta; % Fit curve

figure %[output:3072c234]
plot(timeTrain, yTrain, 'Color', [0.7 0.7 0.7]); hold on %[output:3072c234]
plot(timeTrain, yFourier, 'r', 'LineWidth', 2); hold off %[output:3072c234]
legend('yNorm', 'Fourier fit'); title(sprintf('Yearly Fourier fit, K = %d', K)) %[output:3072c234]
%%
%[text] Get residuals between yearly fourier and yNorm - this is what we will use SARIMA on. h = 1 -\> stationary
yRes = yTrain - yFourier;
figure; plot(timeTrain, yRes); title('Residuals after yearly Fourier fit') %[output:02d4d2d0]
h = adftest(yRes) %[output:09a6835c]

figure; autocorr(yRes, NumLags=40); title('ACF of residuals') %[output:112ca6cb]
figure; parcorr(yRes, NumLags=40); title('PACF of residuals') %[output:638ddc99]
%[text] p = 1, q = 0
%[text] P = 1, Q = 0 or P = 0, Q = 1 (try both options)
%[text] also try P = Q  = 1
%[text] s = 7
%%
%[text] **Fit joint model — Fourier and SARIMA**
%[text] Parameters
%[text] (1, 0, 0) - baseline AR(1) model
%[text] (1, 0, 0) x (1, 0, 0)\_7 - seasonal AR
%[text] (1, 0, 0) x (0, 0, 1)\_7 - seasonal MA
%[text] (1, 0, 0) x (1, 0, 1)\_7 - seasonal ARMA
%[text] 
models = {}; % {name, model, X}

n = numel(yTrain);

% Fourier
K = 2; m = 365.25;
tTrain = days(timeTrain - timeTrain(1));

Xfourier = zeros(n, 2*K); % Two cols per harmonic
for k = 1:K
    Xfourier(:, 2*k-1) = sin(2*pi*k*tTrain/m);
    Xfourier(:, 2*k) = cos(2*pi*k*tTrain/m);
end

% [p q P Q]
candidates = [ 1 0 0 0;    % #1 AR(1) baseline %[output:group:159ec624] %[output:7cdfae83]
    1 0 1 0;    % #2 + seasonal AR(7) %[output:7cdfae83]
    1 0 0 1;    % #3 + seasonal MA(7) %[output:7cdfae83]
    1 0 1 1;]    % #4 + ARMA %[output:group:159ec624] %[output:7cdfae83]

nC = size(candidates,1);

for i = 1:nC
    c = num2cell(candidates(i,:));
    [p,q,P,Q] = c{:};
    [mdl, ~, ~] = fitRegSARIMA(yTrain, Xfourier, p, q, P, Q);

    name = sprintf('Fourier w/ (%d,0,%d)x(%d,0,%d)_7', p, q, P, Q);
    models(end+1, :) = {name, mdl, Xfourier};
end
%%
%[text] ### Weekday Dummy model
%[text] Adds dummy variables for each day of the week. This way, the model can use the day of the week as a feature, rather than **only** using influence from the last day of the week (e.g. using last Tuesday to influence this Tuesday). This model does both.
trainDOW = dummyvar(weekday(timeTrain(:))); % One hot encoding for day of week
trainDOW = trainDOW(:, 2:7); % Drop Sunday

X = [Xfourier trainDOW];

p = 1; q = 0; P = 1; Q = 1;
[mdl, ~, ~] = fitRegSARIMA(yTrain, X, p, q, P, Q);
name = sprintf('Fourier + Weekday Dummy w/ (%d,0,%d)x(%d,0,%d)_7', p, q, P, Q);
models(end+1, :) = {name, mdl, X};
summarize(mdl) %[output:3256a7b9]
%%
%[text] Sunday Dummy Variable
%[text] Looking at the summary from the weekday dummy model, the values of Beta(5:10) (corresponding to Monday - Saturday) are all similar, but statistically significant. This may indicate that a dummy variable indicating Sunday may be more meaningful - we may be able to capture the same D.O.W. info through a dummy variable that just indicates Sunday or Not Sunday. 
sundayMat = weekday(timeTrain(:)) == 1;
X = [Xfourier sundayMat];

[mdl, ~, ~] = fitRegSARIMA(yTrain, X, 1, 0, 1, 1);   % e.g. #4 + Sunday Dummy
name = sprintf('Fourier & Sunday Dummy w/ (%d,0,%d)x(%d,0,%d)_7', p, q, P, Q);
models(end+1, :) = {name, mdl, X};
summarize(mdl) %[output:4fa625da]
%%
%[text] Weekend Dummy Variable
%[text] Similar idea to above. Since in the DOW model, the Saturday feature was not statistically significant, it logically makes sense to try a weekend dummy variable.
weekendMat = weekday(timeTrain(:)) == 1 | weekday(timeTrain(:)) == 7;
X = [Xfourier weekendMat];

[mdl, ~, ~] = fitRegSARIMA(yTrain, X, 1, 0, 1, 1);   % e.g. #4 + Weekend Dummy
name = sprintf('Fourier & Weekend Dummy w/ (%d,0,%d)x(%d,0,%d)_7', p, q, P, Q);
models(end+1, :) = {name, mdl, X};
summarize(mdl) %[output:3e918730]
%[text] From the results, seems like Sunday is a better indicator
%%
%[text] Refit the four models above, but with the sunday indicator
X = [Xfourier sundayMat];
for i = 1:size(candidates,1)
    c = num2cell(candidates(i,:));
    [p,q,P,Q] = c{:};
    [mdl, ~, ~] = fitRegSARIMA(yTrain, X, p, q, P, Q);
    name = sprintf('Fourier + Sunday Dummy w/ (%d,0,%d)x(%d,0,%d)_7', p, q, P, Q);
    models(end+1, :) = {name, mdl, X};
end
%%
%[text] Save models
save('sarima_models.mat', 'models', 'yTrain', 'yTest', 'yTrainRaw', ...
    'yTestRaw', 'timeTrain', 'timeTest', 'yTrainMean', 'yTrainStd', ...
    'tAll', 'yAll', 'K', 'm');
%%
%[text] Functions
function [EstMdl, logL, numParams] = fitRegSARIMA(y, X, p, q, P, Q)
args = {};
if p > 0, args = [args {'ARLags',  1:p}];     end
if q > 0, args = [args {'MALags',  1:q}];     end
if P > 0, args = [args {'SARLags', 7*(1:P)}]; end
if Q > 0, args = [args {'SMALags', 7*(1:Q)}]; end

Mdl = regARIMA(args{:});              % intercept included by default (d = D = 0)
[EstMdl, ~, logL] = estimate(Mdl, y, 'X', X, 'Display', 'off');

% intercept + betas + AR + MA + SAR + SMA + innovation variance
numParams = 1 + size(X,2) + p + q + P + Q + 1;
end

